def bayes(prior: float, sensitivity: float, false_positive: float) -> float:
    """已知患病率先验、检测灵敏度与假阳性率，求阳性时真实患病概率。"""
    p_positive = sensitivity * prior + false_positive * (1 - prior)
    return sensitivity * prior / p_positive

