def fib_iter(n):
    if n < 2:
        return n
    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr
    return curr

def two_sum_sorted(nums, target):
    """有序数组两数之和：相向双指针 O(n)。"""
    left, right = 0, len(nums) - 1
    while left < right:
        total = nums[left] + nums[right]
        if total == target:
            return [left, right]
        if total < target:
            left += 1          # 和太小，左指针右移
        else:
            right -= 1         # 和太大，右指针左移
    return []

def longest_unique_substring(text: str) -> int:
    """最长无重复字符子串：滑动窗口 + 哈希表记录位置。"""
    last_seen = {}
    left = best = 0
    for right, ch in enumerate(text):
        if ch in last_seen and last_seen[ch] >= left:
            left = last_seen[ch] + 1     # 收缩到重复字符之后
        last_seen[ch] = right
        best = max(best, right - left + 1)
    return best

def min_window(nums, target):
    """和大于等于 target 的最短连续子数组长度（均为正数）。"""
    left = total = 0
    best = float("inf")
    for right, value in enumerate(nums):
        total += value
        while total >= target:           # 满足条件就尝试收缩
            best = min(best, right - left + 1)
            total -= nums[left]
            left += 1
    return 0 if best == float("inf") else best

def subsets(nums):
    result = []
    def backtrack(start, path):
        result.append(path[:])            # 每个节点都是合法解
        for i in range(start, len(nums)): # start 保证不重复、不回看
            path.append(nums[i])
            backtrack(i + 1, path)
            path.pop()
    backtrack(0, [])
    return result

def combination_sum(candidates, target):
    result = []
    def backtrack(start, remaining, path):
        if remaining == 0:
            result.append(path[:]); return
        if remaining < 0:
            return                        # 剪枝：已超目标
        for i in range(start, len(candidates)):
            path.append(candidates[i])
            backtrack(i, remaining - candidates[i], path)   # 可重复选：传 i
            path.pop()
    backtrack(0, target, [])
    return result

import heapq

def max_meetings(intervals):
    """最多不重叠会议：按结束时间升序贪心。"""
    intervals = sorted(intervals, key=lambda x: x[1])
    count, last_end = 0, float("-inf")
    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
    return count

def min_coins(coins, amount):
    """硬币找零：面值不保证规范时必须用 DP，这里给出通用解。"""
    dp = [float("inf")] * (amount + 1)
    dp[0] = 0
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value:
                dp[value] = min(dp[value], dp[value - coin] + 1)
    return -1 if dp[amount] == float("inf") else dp[amount]

def schedule_tasks(tasks):
    """按截止时间安排任务，超期时丢弃最耗时的任务。"""
    tasks.sort(key=lambda t: t[1])
    chosen, total = [], 0
    for duration, deadline in tasks:
        total += duration
        heapq.heappush(chosen, -duration)
        if total > deadline:
            total += heapq.heappop(chosen)   # 弹出的负数等于减去该耗时
    return len(chosen)

class TrieNode:
    __slots__ = ("children", "is_end", "count")
    def __init__(self):
        self.children = {}
        self.is_end = False      # 是否是某个单词的结尾
        self.count = 0           # 经过该节点的单词数（用于前缀统计）

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
            node.count += 1
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return node is not None and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._walk(prefix) is not None

    def count_prefix(self, prefix: str) -> int:
        node = self._walk(prefix)
        return node.count if node else 0

    def _walk(self, text: str):
        node = self.root
        for ch in text:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

class Fenwick:
    """单点修改 + 区间求和，代码短、常数小。"""

    def __init__(self, n: int):
        self.n = n
        self.tree = [0] * (n + 1)

    def add(self, index: int, delta: int) -> None:
        i = index + 1                     # 内部下标从 1 开始
        while i <= self.n:
            self.tree[i] += delta
            i += i & -i                   # lowbit：跳到下一个管辖区间

    def prefix_sum(self, index: int) -> int:
        """前 index 个元素之和（下标 0..index-1）。"""
        total, i = 0, index
        while i > 0:
            total += self.tree[i]
            i -= i & -i
        return total

    def range_sum(self, left: int, right: int) -> int:
        """闭区间 [left, right] 的和。"""
        return self.prefix_sum(right + 1) - self.prefix_sum(left)

from collections import deque

def next_greater(nums):
    """下一个更大元素的下标；不存在记 -1。"""
    result = [-1] * len(nums)
    stack = []                       # 存下标，对应值单调递减
    for i, value in enumerate(nums):
        while stack and nums[stack[-1]] < value:
            result[stack.pop()] = i
        stack.append(i)
    return result

def largest_rectangle(heights):
    """柱状图中最大矩形：单调递增栈，两端补 0 作哨兵。"""
    stack, best = [], 0
    for i, h in enumerate(list(heights) + [0]):
        while stack and heights[stack[-1]] > h:
            height = heights[stack.pop()]
            width = i if not stack else i - stack[-1] - 1
            best = max(best, height * width)
        stack.append(i)
    return best

def sliding_window_max(nums, k):
    """滑动窗口最大值：单调递减队列，队首即最大值。"""
    queue = deque()                  # 存下标
    result = []
    for i, value in enumerate(nums):
        while queue and nums[queue[-1]] <= value:
            queue.pop()              # 比新元素小的都不可能是最大值
        queue.append(i)
        if queue[0] <= i - k:        # 队首已滑出窗口
            queue.popleft()
        if i >= k - 1:
            result.append(nums[queue[0]])
    return result

def binary_answer(low, high, feasible):
    """求满足 feasible(x) 的最小 x（feasible 随 x 单调递增为真）"""
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid          # mid 可行，尝试更小
        else:
            low = mid + 1       # mid 不可行，必须更大
    return low

import hashlib
import math

class BloomFilter:
    """布隆过滤器：只会假阳性，绝不会有假阴性。"""

    def __init__(self, capacity: int, error_rate: float = 0.01):
        self.m = max(1, int(-capacity * math.log(error_rate) / (math.log(2) ** 2)))
        self.k = max(1, int((self.m / capacity) * math.log(2)))
        self.bits = bytearray((self.m + 7) // 8)
        self.count = 0

    def _positions(self, item: str):
        data = item.encode("utf-8")
        for i in range(self.k):
            digest = hashlib.blake2b(data, digest_size=8, salt=str(i).encode()).digest()
            yield int.from_bytes(digest, "big") % self.m

    def add(self, item: str) -> None:
        for pos in self._positions(item):
            self.bits[pos >> 3] |= 1 << (pos & 7)
        self.count += 1

    def might_contain(self, item: str) -> bool:
        return all(
            self.bits[pos >> 3] & (1 << (pos & 7)) for pos in self._positions(item)
        )

