def is_convex_1d(f, low: float, high: float, samples: int = 200) -> bool:
    """一维凸性数值判定：检查中点函数值是否不超过两端平均。"""
    step = (high - low) / samples
    for i in range(samples + 1):
        x1, x3 = low + i * step, low + min(i + 2, samples) * step
        x2 = (x1 + x3) / 2
        if f(x2) > (f(x1) + f(x3)) / 2 + 1e-9:
            return False
    return True

