# 递归版：栈深度 O(n)
def sum_rec(n):
    return 0 if n == 0 else n + sum_rec(n - 1)

# 迭代版：栈深度 O(1)
def sum_iter(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

