# 热点读打散：写时复制成 N 份，读时随机选一份
import random

SHARDS = 8

def write(redis, key: str, value: str) -> None:
    for i in range(SHARDS):
        redis.set(f"{key}#{i}", value)

def read(redis, key: str) -> str | None:
    return redis.get(f"{key}#{random.randint(0, SHARDS - 1)}")

